function readiness(worker,project){const reqs=model.projectRequirements.filter(r=>r.project_id===project).map(r=>r.requirement_id);const missing=reqs.filter(id=>!model.docs.some(d=>d.worker_id===worker&&d.project_id===project&&d.requirement_id===id&&d.state==='approved'&&d.has_file&&d.expires_on>=today()));return {worker_id:worker,configured:reqs.length>0,ready:reqs.length>0&&!missing.length,blocking_count:missing.length,required_count:reqs.length};}
