function assignmentPreview(p){need('plan.write');if(!model.workers.some(w=>w.id===p.worker_id))fail('Selecciona un colaborador válido.',422);const list=days(p.starts_on,p.ends_on),service=model.services.find(s=>s.id===p.service_id);if(p.state==='terrain'&&(!service||service.status==='completed'||service.status==='cancelled'||p.starts_on<service.starts_on||p.ends_on>service.ends_on))fail('Selecciona un servicio activo cuyo período cubra las fechas.');if(!['terrain','rest','unassigned'].includes(p.state))fail('Estado no válido.',422);if(p.state!=='terrain'&&p.service_id!==null)fail('El descanso no debe tener servicio.',422);const existing=model.assignments.filter(a=>a.worker_id===p.worker_id&&list.includes(a.work_date));return {days:list.length,conflicts:existing.filter(a=>a.state!=='unassigned'&&(a.state!==p.state||a.service_id!==p.service_id)),expected_versions:Object.fromEntries(existing.map(a=>[a.work_date,a.version])),readiness:service?readiness(p.worker_id,service.project_id):null};}
