  if(route==='/ops/dashboard'){const tomorrow=model.assignments.filter(a=>a.work_date===dateShift(1)&&a.state==='terrain'),tasks=model.tasks.filter(t=>(demoRole==='admin'||t.assignee_id===u.id)&&t.status!=='done'&&(roles[demoRole].includes('documents.read')||!t.document_id));return {active_services:model.services.filter(s=>['scheduled','active'].includes(s.status)).length,pending_tasks:tasks.length,overdue_tasks:tasks.filter(t=>t.due_on<today()).length,tomorrow_assignments:tomorrow.length,tomorrow_blocked:tomorrow.filter(a=>!readiness(a.worker_id,model.services.find(s=>s.id===a.service_id).project_id).ready).length,basis:'fictitious_records'};}
